from pathlib import Path
import hashlib, json
from PIL import Image

HERE = Path(__file__).resolve().parent
def sha(path):
    return hashlib.sha256(path.read_bytes()).hexdigest()

def compose():
    manifest = json.loads((HERE / "preview-manifest.json").read_text())
    w, h = manifest["canvas_size_px"]
    canvas = Image.new("RGBA", (w, h), (0, 0, 0, 0))
    for layer in sorted(manifest["layers"], key=lambda item: item["z"]):
        path = HERE / layer["registered_file"]
        if sha(path) != layer["registered_sha256"]:
            raise ValueError("Layer changed: " + path.name)
        im = Image.open(path).convert("RGBA")
        if im.size != (w, h):
            raise ValueError("Registered layer canvas mismatch")
        canvas = Image.alpha_composite(canvas, im)
    canvas.save(HERE / "assembled-preview.png")
    canvas.convert("RGB").save(HERE.parent / "scene.png")
    return canvas

if __name__ == "__main__":
    compose()

